@mcp.resource("notes://all")
def all_notes() -> str:
    """Return every saved note as a single text block."""
    return "\n\n".join(n.body for n in load_notes())

@mcp.resource("notes://{note_id}")
def one_note(note_id: str) -> str:
    """Return a single note by its ID."""
    note = find_note(note_id)
    if note is None:
        raise ValueError(f"No note with id {note_id}")
    return note.body

@mcp.prompt()
def summarize_note(note_id: str) -> str:
