    note = find_note(note_id)
    return f"Summarize the following note in two sentences:\n\n{note.body}"

from pydantic import BaseModel

class CreateNoteInput(BaseModel):
    title: str
    body: str
    tags: list[str] = []

@mcp.tool()
def create_note(input: CreateNoteInput) -> str:
    """Create a new note and return its generated ID."""
    note = save_note(input.title, input.body, input.tags)
    return note.id

