from mcp.server.fastmcp import FastMCP

mcp = FastMCP("tasks-server")
TASKS = []

@mcp.tool()
def add_task(title: str) -> str:
    """Add a new task and return its position in the list."""
    TASKS.append(title)
    return f"Added as task #{len(TASKS)}"

@mcp.resource("tasks://all")
def all_tasks() -> str:
    """List every current task."""
    return "\n".join(f"{i + 1}. {t}" for i, t in enumerate(TASKS))

@mcp.prompt()
def plan_my_day() -> str:
    """Build a prompt asking for a plan based on current tasks."""
    return "Given these tasks, suggest an order to tackle them today:\n" + "\n".join(TASKS)

if __name__ == "__main__":
    mcp.run()

@mcp.tool()
def convert_temp(value: float, to_unit: str) -> float:
    """Convert a temperature to 'celsius' or 'fahrenheit'."""
    if to_unit == "fahrenheit":
        return value * 9 / 5 + 32
    if to_unit == "celsius":
        return (value - 32) * 5 / 9
    raise ValueError("to_unit must be 'celsius' or 'fahrenheit'")
